window.HADITH_BOOKS[9] = [{"id": 6295, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 1, "arabic": "عَنْ عُمَرَ بْنِ الْخَطَّابِ رَضِيَ اﷲِ ُ تَعَالیٰ عَنْہُ قَالَ:قَالَ: رَسُوْلُ اﷲِ صَلَّی اﷲ ُ عَلَیْہِ وَسَلَّمَ إِنَّمَا الْاَعْمَالُ بِالنِّیَّاتِ وإِنَّمَا لِکُلِّ إمْرِئٍ مَّا نَوٰی فَمَنْ کَانَتْ ھِجْرَتُہٗ اِلَی اﷲ ِ وَرَسُولِہ ِ فَھِجْرَتُہٗ اِلَی اﷲ ِ وَرَسُولِہٖ وَمَنْ کَانَتْ ھِجْرَتُہٗ اَلٰی دُنْیَا یُصِیْبُھَا اَوِ إمْرَأَۃٍ یَتَزَوَّجُھَا ھِجْرَتُہٗ إِلٰی مَا ھَاجَرَ إِلَیْہِ‘‘۔ مُتَّفَقٌ عَلَیْہِ .(صحیح البخاری ۱/۳ ، الصحیح لمسلم ۱/ ۱۴۰ ، سنن ابی داؤد ۱/۳۰۰ ،النسائی ۱/۲۴)", "urdu": "حضرت سیدنا عمر بن الخطاب رضی اﷲ عنہ سے روایت ہے کہا انہوں نے ،فرمایا رسول کریم صلّی اﷲ علیہ واٰلہٖ وسلّم نے ،سوائے اس کے نہیں اعمال ( کا اعتبار اور خدا کی درگاہ میں قبولیت) نیتوں(1)کے ساتھ ہے ۔یعنی کوئی عمل بدونِ نیت معتبر اور مقبول نہیں ۔اور کسی آدمی کو اس کے کام میں حصہ یا ثواب نہیں مگر وہی جو اس نے نیت کی پس جس شخص کی ہجرت محض خدا عزوجل اور اس کے رسول صلّی اﷲ علیہ واٰلہٖ وسلّم کیلئے ہو (یعنی اس کی نیت میں طلب رِضا و امتثال امر شارع (اﷲ تعالیٰ و رسول صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کے حکم کی پیروی )ہو) تو اس کی ہجرت خدا عزوجل اور اس کے رسول صلّی اﷲ علیہ واٰلہٖ وسلّم کے لئے ہے ۔(یعنی مقبول ہے اور اس پر ثواب عظیم مترتب ہوتا ہے ) اور جس کی ہجرت محض حصولِ دنیا کے لئے ہو یا کسی عورت سے نکاح کرنے کے لئے ہجرت کرتا ہو (خدا عزوجل اور رسول صلّی اﷲ علیہ واٰلہٖ وسلّم کی رِضامندی کیلئے نہ ہو )تو اس کی ہجرت اسی چیز کی طرف ہے جس کی طرف اس نے ہجرت کی یعنی حصول دنیا یا نکاح ۔ اس کو بخاری و مسلم نے روایت کیا ہے۔\n (1) امام احمد رضا محدث بریلوی قدس سرہ فرماتے ہیں :بیشک جو علم نیت جانتا ہے ایک ایک فعل کو اپنے لئے کئی کئی نیکیاں کر سکتا ہے مثلاً ، جب نماز کیلئے مسجد کو چلا اور صرف یہی قصد ہے کہ نماز پڑھو نگا تو بے شک اس کا یہ چلنا محمود ،ہر قدم پر ایک نیکی لکھیں گے اور دوسرے پر گناہ محو کریں گے مگر عالم نیت اس ایک فعل میں اتنی نیتیں کرسکتا ہے اصل مقصود یعنی نماز کو جاتا ہوں(۲)خانۂ خدا کی زیارت کرونگا(۳) شعار اسلام ظاہر کرونگا (۴)داعی الی اﷲ کی اجابت کرتا ہوں(۵) تحیۃ المسجد پڑھنے جاتا ہوں(۶) مسجد سے خس و خاشاک وغیرہ دور کرونگا(۷) اعتکاف کرنے جاتا ہوں کہ مذہب مفتیٰ بہ پر(نفلی) اعتکاف کیلئے روزہ شرط نہیں ۔ایک ساعت کا بھی ہوسکتا ہے ، جب سے داخل ہو باہر آنے تک اعتکاف کی نیت کرے ۔ انتظار نماز و ادائے نماز کے ساتھ اعتکاف کا بھی ثواب پائے گا۔ (۸) امر الٰہی ’’ خُذُوْا زِیْنَتَکُمْ عِنْدَ کُلِّ مَسْجِدٍ‘‘ (اپنی زینت لو جب مسجد جاؤ) کے امتثال کو جاتا ہوں ۔ (۹) جو وہاں علم والا ملے گا اس سے مسائل پوچھوںگا، دین کی باتیں سیکھوں گا (۱۰) جاہلوں کو مسئلہ بتاؤںگا، دین سکھاؤں گا (۱۱)جو علم میں میرے برابر ہوگا اس سے علم کی تکرار کروں گا (۱۲) علماء کی زیارت (۱۳) نیک مسلمان کا دیدار (۱۴)دوستوں سے ملاقات(۱۵) مسلمانوں سے میل (۱۶) جو رشتہ دار ملیں گے ان سے بکشادہ پیشانی مل کر صلۂ رحمی (۱۷) اہل اسلام کو سلام (۱۸) مسلمانوں سے مصافحہ کروںگا (۱۹) ان کے سلام کا جواب دوں گا (۲۰) نماز باجماعت میں مسلمانوں کی برکتیں حاصل کروں گا (۲۱) و (۲۲) مسجد میں جاتے نکلتے حضور سید عالم پر سلام عرض کروں گا(۲۳) و (۲۴) دخول و خروج میں حضور و آل حضور و ازواج حضورپر درود بھیجوں گا اللھم صلی علی سیدنا محمد وعلی ال سیدنا محمد وعلی أزواج سیدنا محمد صلّی اﷲ علیہ واٰلہٖ وسلّم (۲۵) بیمار کی مزاج پرسی کروں گا (۶ ۲) اگر کوئی غمی والا ملا تعزیت کروں گا (۲۷) جس مسلمان کو چھینک آئی اور اس نے ’ الحمد ﷲ ‘ کہا اسے ’ یرحمک اﷲ ‘ کہوں گا(۲۸)امر بالمعروف (۲۹)و نہی عن المنکر کروں گا (۳۰)نمازیوں کو وضو کا پانی دوں گا (۳۱)و (۳۲)خود مؤذن ہے ، یا مسجد میں کوئی مؤذن مقرر نہیں تو نیت کرے کہ اذان و اقامت کہوں گا۔اب یہ کہنے نہ پایا یا دوسرے نے کہہ دی تاہم اپنی نیت کا ثواب پاچکا ، فَقَدْ وَقَعَ أجَرُہ‘ عَلٰی اﷲِ (۳۳)جو راہ بھولا ہوگا اُسے راستہ بتاؤں گا(۳۴)اندھے کی دستگیری کروں گا (۳۵) جنازہ ملا تو نماز پڑھوں گا (۳۶)موقع پایاتوساتھ دفن تک جاؤں گا۔ (۳۷)دومسلمانوں میں نزاع ہوئی", "roman": "Hazrat Sayyiduna Umar Bin Al-Khattab Radiyallahu Anhu se Riwayat hai kaha unhon ne, farmaya Rasool-e-Kareem Sallallahu Alaihi Wasallam ne, siwaye is ke nahin a'maal (ka e'tibar aur Khuda ki dargah mein qubooliyat) niyyaton(1) ke saath hai. Ya'ni koi amal badoon-e-niyyat mu'tabar aur maqbool nahin. Aur kisi aadmi ko us ke kaam mein hissa ya sawab nahin magar wahi jo us ne niyyat ki pas jis Shakhs ki hijrat mahz Khuda Azza wa Jall aur us ke Rasool Sallallahu Alaihi Wasallam ke liye ho (ya'ni us ki niyyat mein talab-e-raza wa imtisal-e-amr-e-shari' (Allah Ta'ala wa Rasool Sallallahu Alaihi Wasallam ke Hukm ki pairwi) ho) to us ki hijrat Khuda Azza wa Jall aur us ke Rasool Sallallahu Alaihi Wasallam ke liye hai. (Ya'ni maqbool hai aur is par sawab-e-azeem murattab hota hai) aur jis ki hijrat mahz husool-e-dunya ke liye ho ya kisi Aurat se Nikah karne ke liye hijrat karta ho (Khuda Azza wa Jall aur Rasool Sallallahu Alaihi Wasallam ki razamandi ke liye na ho) to us ki hijrat usi cheez ki taraf hai jis ki taraf us ne hijrat ki ya'ni husool-e-dunya ya Nikah. Is ko Bukhari wa Muslim ne Riwayat kiya hai.\n(1) Imam Ahmad Raza Muhaddis Barelvi Qaddasa Sirruhu farmate hain: Beshak jo Ilm-e-niyyat janta hai ek ek fa'il ko apne liye kayi kayi nekiyan kar sakta hai maslan, jab Namaz ke liye Masjid ko chala aur Sarf yahi qasd hai ke Namaz padhunga to beshak us ka yeh chalna mahmood, har qadam par ek neki likhenge aur doosre par gunah mahw karenge magar aalim-e-niyyat is ek fa'il mein itni niyyaten kar sakta hai asal maqsood ya'ni Namaz ko jata hoon (2) Khana-e-Khuda ki Ziyarat karunga (3) Shi'aar-e-Islam zahir karunga (4) Da'i il-Allah ki ijabat karta hoon (5) Tahiyyat-ul-Masjid padhne jata hoon (6) Masjid se khas-o-khashak waghairah door karunga (7) I'tikaf karne jata hoon ke mazhab-e-mufti bihi par (nafli) I'tikaf ke liye Roza shart nahin. Ek saa'at ka bhi ho sakta hai, jab se dakhil ho bahar aane tak I'tikaf ki niyyat kare. Intezar-e-Namaz wa ada-e-Namaz ke saath I'tikaf ka bhi sawab payega. (8) Amr-e-Ilahi \"Khuzoo zeenatakum inda kulli Masjidin\" (Apni zeenat lo jab Masjid jao) ke imtisal ko jata hoon. (9) Jo wahan Ilm wala milega us se masa'il poochhunga, deen ki baatein seekhunga (10) Jahilon ko Mas'ala bataunga, deen sikhaunga (11) Jo Ilm mein mere barabar hoga us se Ilm ki takraar karunga (12) Ulama ki Ziyarat (13) Naik Musalman ka deedar (14) Doston se mulaqat (15) Musalmanon se meil (16) Jo rishtadar milenge un se kushadah peshani mil kar sila-e-rehmi (17) Ahl-e-Islam ko Salam (18) Musalmanon se musafaha karunga (19) Un ke Salam ka Jawab doonga (20) Namaz ba-Jama'at mein Musalmanon ki barkatein hasil karunga (21) wa (22) Masjid mein jaate nikalte Huzoor Sayyid-e-Aalam par Salam arz karunga (23) wa (24) Dukhool wa khurooj mein Huzoor wa Aal-e-Huzoor wa Azwaj-e-Huzoor par Durood bhejunga \"Allahumma Salli Ala Sayyidina Muhammadinw wa Ala Aali Sayyidina Muhammadinw wa Ala Azwaji Sayyidina Muhammadin Sallallahu Alaihi Wasallam\" (25) Beemar ki mizaj pursi karunga (26) Agar koi ghami wala mila Ta'ziyat karunga (27) Jis Musalman ko chheenk aayi aur us ne 'Alhamdulillah' kaha use 'Yarhamukallah' kahunga (28) Amr bil Ma'Roof (29) wa Nahi anil Munkar karunga (30) Namaziyon ko Wazu ka pani doonga (31) wa (32) Khud mo'azzin hai, ya Masjid mein koi mo'azzin muqarrar nahin to niyyat kare ke Azan wa Iqamat kahunga. Ab yeh kehne na paya ya doosre ne keh di taham apni niyyat ka sawab pa chuka, \"Faqad waqa'a ajruhoo alallah\" (33) Jo raah bhoola hoga use raasta bataunga (34) Andhe ki dastgeeri karunga (35) Janazah mila to Namaz padhunga (36) Mauqa paya to saath dafan tak jaunga. (37) Do Musalmanon mein niza' hui"}, {"id": 6296, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 2, "arabic": "عَنْ مَعَاذِ بْنِ جَبَلٍ أنَّ رَسُوْلَ اﷲ ِ صَلَّی اﷲ ُ تَعَالیٰ عَلَیْہِ وَسَلَّمَ لَمَّا بَعَثَہٗ إِلَی الْیَمَنِ قَالَ کَیْفَ تَقْضِي إِذَا عَرَضَ لَکَ قَضَآءٌ ؟ قَالَ أَقْضِيْ بِکِتَابِ اﷲ ِ قَالَ فَإنْ لَّمْ تَجِدْ فِيْ کِتَابِ اﷲ ِ ؟قَالَ فَبِسُنَّۃِ رَسُوْلِ اﷲ ِ صَلَّی اﷲ ُ تَعَالیٰ عَلَیْہِ وَسَلَّمَ قَالَ فَإنْ لَّم تَجِدْ فِيْ سُنَّۃِ رَسُوْلِ اﷲ ِ صَلَّی اﷲ ُ تَعَالیٰ عَلَیْہِ وَسَلَّمَ قَالَ أَجْتَھِدُ رَأیِيْ وَلا اٰلُوْا قَالَ فَضَرَبَ رَسُوْلُ اﷲ ِ صَلَّی اﷲ ُ تَعالیٰ عَلَیْہِ وَسَلَّمَ فِيْ صَدْرِہٖ قَالَ الْحَمْدُ لِلّٰہِ الَّذِيْ وَفَّقَ رَسُوْلَ رَسُوْلِ اﷲ ِ لِمَا یَرْضٰی بِہٖ رَسُوْلُ اﷲ ِ ۔رَوَاہُ الْتِّرْمِذِیُ وَ أَبُوْ دَاؤُدَ وَالْدَّارَمِيُّ ..(جَامِعُ الْتِرْمِذِیْ ۳/۶۱۶‘ سُنَنِ اَبِیْ دَاؤد ۳/۳۰۳‘ الدارمی ۱/۷۲‘ )", "urdu": "حضرت سیدنا معاذ بن جبل رضی اﷲ عنہ سے روایت ہے کہ جب ان کو رسول اﷲ صلّی اﷲ علیہ واٰلہٖ وسلّم نے یمن کی طرف قاضی بناکر بھیجا تو فرمایا کہ جب تجھے کوئی معاملہ پیش آئے تو تُو کیسے فیصلہ کرے گا۔ حضرت سیدنا معاذ رضی اﷲ عنہ نے عرض کیا کہ میں اﷲ عزوجل کی کتاب کے ساتھ حکم کروں گا۔ آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے فرمایا اگر اﷲ عزوجل کی کتاب میں تو اس کا حکم نہ پائے تو پھر کیا کرے گا۔ انہوں نے عرض کی کہ رسول کریم صلّی اﷲ علیہ واٰلہٖ وسلّم کی سنت کے ساتھ فیصلہ کروں گا۔ آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے فرمایا اگر تو رسول علیہِ السّلام کی سنت میں بھی اس حکم کو نہ پائے تو پھر کیا کرے گا ؟ انہوں نے عرض کی کہ میں اپنی عقل او ر رائے کے ساتھ اجتہاد کروں گا اور طلب ثواب میں کمی نہ کروں گا۔ حضرت سیّدنا معاذ رضی اﷲ عنہ کہتے ہیں پھررسول کریم رؤف رحیم صلّی اﷲ علیہ واٰلہٖ وسلّم نے میرے سینہ پر ہاتھ مارا اور فرمایا الحمد ﷲ عزوجل کہ اﷲ تعالیٰ نے اپنے رسول صلّی اﷲ علیہ واٰلہٖ وسلّم کے قاصد کو اس چیز کی توفیق دی جس کے ساتھ اﷲ تعالیٰ عزوجل کا رسول صلّی اﷲ علیہ واٰلہٖ وسلّم راضی ہے۔", "roman": "Hazrat Sayyiduna Mu'az Bin Jabal Radiyallahu Anhu se Riwayat hai ke jab un ko Rasoolullah Sallallahu Alaihi Wasallam ne Yaman ki taraf qaazi banakar bheja to farmaya ke jab tujhe koi ma'amla pesh aaye to tu kaise faisla karega. Hazrat Sayyiduna Mu'az Radiyallahu Anhu ne arz kiya ke main Allah Azza wa Jall ki Kitaab ke saath Hukm karunga. Aap Sallallahu Alaihi Wasallam ne farmaya agar Allah Azza wa Jall ki Kitaab mein tu us ka Hukm na paaye to phir kya karega. Unhon ne arz ki ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ki Sunnat ke saath faisla karunga. Aap Sallallahu Alaihi Wasallam ne farmaya agar tu Rasool Alayhis Salam ki Sunnat mein bhi us Hukm ko na paaye to phir kya karega? Unhon ne arz ki ke main apni aql aur raye ke saath ijtihad karunga aur talab-e-sawab mein kami na karunga. Hazrat Sayyiduna Mu'az Radiyallahu Anhu kehte hain phir Rasool-e-Kareem Raoof-ur-Raheem Sallallahu Alaihi Wasallam ne mere seene par haath maara aur farmaya: Alhamdu Lillahi Azza wa Jall ke Allah Ta'ala ne apne Rasool Sallallahu Alaihi Wasallam ke qasid ko us cheez ki taufeeq di jis ke saath Allah Ta'ala Azza wa Jall ka Rasool Sallallahu Alaihi Wasallam raazi hai."}, {"id": 6297, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 3, "arabic": "عَنْ رَافِعِ بْنِ خُدَیْج قَالَ :سَمِعْتُ رسول اﷲ صَلَّی اﷲ تعالیٰ عَلَیْہِ وَسَلَّمَ یَقُوْلُ أَسْفِرُوْا بِالْفَجْرِ فَإِنَّہ‘ أَعْظَمُ لِلْأجْرِ ۔ رَوَاہٗ التِّرْمِذِیُّ وَ قَالَ حَسَنٌ صَحِیْحٌ وَ اَبُوْ دَاؤُدَ وَ الدَّارِمِیُّ. (جَامِعُ الْتِرْمِذِیِّ بَابُ مَا جَاءَ بِالْاِسْفَارِ بِالْفَجْرِ۱/۴۰ ‘ اَلْسُنَنْ لِاَبِیْ داؤدَ ۱/۶۱، اَلْدَّارَمِیُّ ۱/۳۰۰۔ )", "urdu": "حضرت سیدنا رافع بن خدیج رضی اﷲ عنہ سے روایت ہے کہ انہوں نے کہا کہ سنا میں نے رسول کریم رؤف رحیم صلّی اﷲ علیہ واٰلہٖ وسلّم کو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم فرماتے تھے کہ نماز فجر میں اسفار کرو یعنی روشنی میں ادا کرو۔کیونکہ اس کا روشنی میں ادا کرنااجر میں بہت بڑا ہے ۔", "roman": "Hazrat Sayyiduna Rafi' Bin Khadeej Radiyallahu Anhu se Riwayat hai ke unhon ne kaha ke suna main ne Rasool-e-Kareem Raoof-ur-Raheem Sallallahu Alaihi Wasallam ko, Aap Sallallahu Alaihi Wasallam farmate the ke Namaz-e-Fajr mein isfaar karo ya'ni roshni mein ada karo, kyunke is ka roshni mein ada karna ajr mein bohot bada hai."}, {"id": 6298, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 4, "arabic": "عَنْ أَبِيْ ذَرٍّ رَضِیَ ﷲُ عَنْہُ قَالَ کُنَّا مَعَ الْنَّبِي صَلَّی اﷲُ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم فَأَرَادَ الْمُؤَذِّنُ أَنْ یُؤَذِّنَ فَقَالَ لَہ ‘ اَبْرِدْ ثُمَّ اَرَادَ اَنْ یُّؤَذِّنَ فَقَالَ لَہ ‘ اَبْرِدْ ثُمَّ اَرَادَ أنْ یُّؤَذِّنَ فَقَالَ لَہ ‘ اَبْرِدْ حَتّٰی سَاوَی الْظِّلُّ التَّلُوْلَ فَقَال الْنَّبِيُّ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم إِنَّ شِدَّۃَ الْحَرِّ مِنْ فَیْحِ جَھَنَّمَ ۔رَوَاہٗ الْبُخَارِيُّ. (صحیح البخاری ۱/۸۷ باب الاذان‘الصحیح لمسلم باب استحباب الابراد بالظہر ۱/۴۳۰۔ )", "urdu": "حضرت سیدنا ابو ذر غفاری رضی اﷲ عنہ سے روایت ہے کہ انہوں نے کہا کہ ہم رسول کریم صلّی اﷲ علیہ واٰلہٖ وسلّم کے ہمراہ سفر میں تھے ۔مؤذن نے اذان دینے کا ارادہ کیا تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے فرمایا ٹھنڈا کرو یعنی وقت ٹھنڈا ہونے د و ۔اس نے پھر تھوڑی دیر کے بعد اذان دینے کاارادہ کیا تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے فرمایا ٹھنڈا ہونے د و۔ اس نے پھر تھوڑی دیر کے بعد اذان کا ارادہ کیا تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے فرمایا اور ٹھنڈا ہونے دو ۔یہاں تک کہ سایہ ٹیلوں کے برابر ہوگیا۔پھر آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے فرمایا کہ گرمی کی شدت دوزخ کے جوش سے ہوتی ہے۔", "roman": "Hazrat Sayyiduna Abu Zarr Ghifari Radiyallahu Anhu se Riwayat hai ke unhon ne kaha ke hum Rasool-e-Kareem Sallallahu Alaihi Wasallam ke hamrah safar mein the. Mo'azzin ne Azan dene ka irada kiya to Aap Sallallahu Alaihi Wasallam ne farmaya thanda karo ya'ni waqt thanda hone do. Us ne phir thodi der ke baad Azan dene ka irada kiya to Aap Sallallahu Alaihi Wasallam ne farmaya thanda hone do. Us ne phir thodi der ke baad Azan ka irada kiya to Aap Sallallahu Alaihi Wasallam ne farmaya aur thanda hone do. Yahan tak ke saaya teelon ke barabar ho gaya. Phir Aap Sallallahu Alaihi Wasallam ne farmaya ke garmi ki shiddat dozakh ke josh se hoti hai."}, {"id": 6299, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 5, "arabic": "عَنْ اَبِيْ ھُرَیْرَۃَ رَضِیَ اﷲ تَعَالٰی عَنْہُ قَالَ :قَالَ رَسُوْلُ اﷲ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم اِذَا اشْتَدَّ الْحَرُّ فَاَبْرِدُوْا بِالصَّلٰوۃِ فَإِنَّ شِدَّۃَ الْحَرِّ مِنْ فَیْحِ جَھَنَّمَ ۔ مُتَّفَقٌ عَلَیْہِ. (صحیح البخاری ۱/ ۱۹۸، الصحیح لمسلم ۱/۴۳۰۔ )", "urdu": "حضرت سیدنا ابوہریرہ رضی اﷲ عنہ سے روایت ہے کہ فرمایا رسول ا کرم صلّی اﷲ علیہ واٰلہٖ وسلّم نے جب گرمی کی شدت ہو تو نماز کو ٹھنڈا کرو کیونکہ گرمی کی شدت جہنم کے جوش سے ہوتی ہے ۔", "roman": "Hazrat Sayyiduna Abu Hurairah Radiyallahu Anhu se Riwayat hai ke farmaya Rasool-e-Akram Sallallahu Alaihi Wasallam ne jab garmi ki shiddat ho to Namaz ko thanda karo kyunke garmi ki shiddat jahannam ke josh se hoti hai."}, {"id": 6300, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 6, "arabic": "عَنْ عَلِیِّ بْنِ شَیْبَانَ قَالَ قَدِمْنَا عَلٰی رَسُوْلِ اﷲِصَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم اَلْمَدِیْنَۃَ فَکَانَ یُؤَخِّرُ الْعَصْرَ مَا دَامَتِ الشَّمْسُ بَیْضَاءَ نَقِیَّۃً ۔رَوَاہُ أَبُوْدَاؤُدُ وَسَکَتَ عَنْہُ۔", "urdu": "ترجمہ :-حضرت علی بن شیبان رضی اﷲ عنہ کہتے ہیں کہ ہم مدینہ شریف میں رسول کریم ، رؤف رحیم صلّی اﷲ علیہ واٰلہٖ وسلّم کی خدمت میں حاضر ہوئے تو آپ عَلَیْہِ السَّلام عصر کی نماز میں تاخیر فرماتے تھے جب تک سورج صاف اور روشن رہتا ۔ (1 ) \n\n\n--------------------------\n(1 ) ..سنن ابی داؤد ۱/۱۱۱", "roman": "Tarjuma: Hazrat Ali bin Shayban Radiyallahu Anhu kehte hain ke hum Madinah Shareef mein Rasool-e-Kareem, Raoof-o-Raheem Sallallahu Alaihi Wasallam ki khidmat mein hazir hue to Aap Alayhis Salam Asr ki Namaz mein takheer farmate the jab tak sooraj saaf aur roshan rehta. (1)\n\n--------------------------\n(1).. Sunan Abi Dawood 1/111"}, {"id": 6301, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 7, "arabic": "عَنْ جَابِرٍ بْنِ عَبْدِ اﷲ قَالَ سَأَلَ رَجُلٌ رَسُوْلَ اﷲِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم عَنْ وَقْتِ الصَّلوٰۃِ فَلَمَّا دَلَکَتِ الشَّمْسُ أَذَّنَ بِلاَلٌ الظُّھْرَ فَأَمَرَہٗ رَسُوْلُ اﷲِصَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم فَأَقَامَ الصَّلٰوۃَ فَصَلّٰی ثُمَّ أَذَّنَ لِلْعَصْرِ حِیْنَ ظَنَنَّا أَنَّ ظِلَّ الرَّجُلِ أَطْوَلُ مِنْہُ فَأَمَرَہُ رَسُوْلُ اﷲ ِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم فَأَقَامَ الصَّلٰوۃَ وَصَلَّی ثُمَّ اَذَّنَ لِلْمَغْرِبِ حِیْنَ غَابَتِ الشَّمْسُ فَأَمَرَہُ رَسُوْلُ اﷲ ِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم فَأَقَامَ الصَّلوٰۃَ وَ صَلَّی ثُمَّ اَذَّنَ لِلْعِشَآءِ حِیْنَ ذَھَبَ بَیَاضُ النَّھَارِ وَ ھُوَ الشَّفَقُ ثُمَّ اَمَرَہُ فَأَقَامَ الصَّلوٰۃَ وَ صَلَّی ثُمَّ اَذَّنَ لِلْفَجْرِ فَأَمَرَہٗ فَأَقَامَ الصَّلوٰۃَ وَصَلَّی ثُمَّ اَذَّنَ بِلاَلُ الْغَدَ لِلظُّھْرِ حِیْنَ دَلَکَتِ الشَّمْسُ فَأَخَّرَھَارَسُوْلُ اﷲ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم حَتّٰی صَارَ ظِلُّ کُلِّ شَیئٍ مِّثْلَیْہِ فَأَمَرَہٗ رَسُوْلُ اﷲ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم فَأَقَامَ وَ صَلَّی ثُمَّ أَذَّنَ لِلْمَغْرِبِ حِیْنَ غَرَبَتِ الشَّمْسُ فَأَخَّرَھَارَسُوْلُ اﷲ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم حَتّٰی کَادَ یَغِیْبُ بِیَاضُ النَّھَارِ وَھُوَ الشَّفَقُ فِیْمَا یُرٰی ثُمَّ اَمَرَہٗ رَسُوْلُ اﷲِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم فَأَقَامَ الصَّلوٰۃَ وَصَلَّی ثُمَّ أَذَّنَ لِلْعِشَاءِ حِیْنَ غَابَ الشَّفَقُ فَنُمْنَا ثُمَّ قُمْنَا مِرَارًا ثُمَّ خَرَجَ إِلَیْنَارَسُوْلُ اﷲ ِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم فَقَالَ مَا اَحَدٌ مِنَ النَّاسِ یَنْتَظِرُ ھٰذِہِ الصَّلوٰۃَ غَیْرُکُمْ فَاِنَّکُمْ فِيْ صَلوٰۃٍ مَاانْتَظَرْتُمُوْھَا وَلَوْلَا اَنْ اَشُقَّ عَلیٰ اُمَّتِي لَاَمَرْتُ بِتَأخِیْرِ ھٰذِہِ الصَّلوٰۃِ إِلَی نِصْفِ الَّیْلِ اَوْ اَقْرَبَ مِنَ اللَّیْلِ ثُمَّ اَذَّنَ لِلْفَجْرِ فَأَخَّرَھَا حَتّٰی کَادَتِ الشَّمْسُ اَنْ تَطْلُعَ فَأَمَرَہٗ فَأَقَامَ الصَّلوٰۃَ فَصَلّٰی ثُمَّ قَالَ، اَلْوَقْتُ فِیْمَا بَیْنَ ھٰذَیْنِ۔ رَوَاہٗ الطَّبرَانِيُّ فِی الْاَوْسَطِ وَ إسْنَادُہٗ حَسَنٌ مَجْمَعُ الزَّوَائِدِ۔", "urdu": "ترجمہ :-حضرتِ جابر بن عبد اﷲ رضی اﷲ عنہفرماتے ہیں کہ ایک شخص نے رسول اﷲصلّی اﷲ علیہ واٰلہٖ وسلّم سے نماز کے اوقات کے متعلق سوال کیا۔تو جب آفتاب ڈھل گیا تو بلالرضی اﷲ عنہ نے ظہر کی آذان دی اس کے بعد آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے حکم دیا تو اس نے تکبیر کہی تو آپ نے نماز پڑھی اس نے عصر کی آذان اس وقت کہی جب کہ ہم نے سمجھا کہ آدمی کاسایہ اس سے بڑھ گیا ہے ۔ اس کے بعد آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے حکم دیا تو انہوں نے تکبیر کہی تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے نماز پڑھی پھر نماز مغرب کی آذان اس وقت دی جبکہ آفتاب غروب ہوگیا۔ اس کے بعد آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے اسے حکم دیا تو اس نے تکبیر کہی تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے نماز مغرب پڑھی ۔پھر عشاء کی آذان اس وقت دی جبکہ دن کی سفیدی یعنی شفق جاتی رہی تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے حکم دیا۔ اس نے تکبیر کہی تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے نماز عشاء پڑھی پھر فجر کی آذان دی اس کے بعد آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے حکم دیا تو انہوں نے تکبیر کہی تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے نماز پڑھی پھر اگلے دن بلال رضی اﷲ عنہ نے ظہر کی آذان اس وقت دی جبکہ آفتاب ڈھل گیا۔ تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے یہاں تک تاخیر کی کہ ہر شے کا سایہ اس کے برابر ہوگیا ۔اس کے بعد آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے حکم دیاتو اس نے تکبیر کہی تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے نماز پڑھ لی۔ پھر اس نے عصر کی آذان دی تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے یہاں تک تاخیر کی کہ ہر شے کا سایہ اس کے دو مثل یعنی دو گنا ہوگیا۔ تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے امر کیا (حکم دیا)تو اس نے تکبیر کہی تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے نماز پڑھ لی۔ پھر اس نے مغرب کی آذان اس وقت دی جبکہ سورج غروب ہوگیا تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے یہاں تک تاخیر فرمائی کہ دن کی سفیدی غائب ہونے کے قریب ہوگئی اور وہ شفق ہے۔ پھر آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے ان کو حکم دیا تو انہوں نے تکبیر کہی تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے نماز پڑھی پھر عشاء کی آذان اس وقت دی جب شفق یعنی دن کی سفیدی غائب ہوگئی پھر ہم سوگئے پھر جاگے ۔ کئی بار ایسا ہوا۔ پھر رسول اﷲ صلّی اﷲ علیہ واٰلہٖ وسلّم ہمارے پاس تشریف لائے اور فرمایا کہ تمہارے سوا کوئی آدمی اس نماز کا انتظار نہیں کررہا۔ پس تم نماز میں ہی ہو جب تک نماز کے انتظار میں رہو۔ اگر یہ بات نہ ہوتی کہ میں تاخیر کا حکم کرکے اپنی امت کو مشقت میں ڈال دونگا تو اس نماز کو نصف شب یا قریب نصف شب تک تاخیر کا حکم دیتا ۔پھر انہوں نے فجر کی آذان دی تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے یہاں تک تاخیر کی کہ آفتاب قریبِ طلوع تھا۔ تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے امر فرمایا تو انہوں نے تکبیر کہی تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے نماز فجر پڑھی ۔پھر فرمایا کہ وقت ان دونوں وقتوں کے درمیان ہے ۔ اس کو طبرانی نے اوسط میں روایت کیا ۔ ( 1)\n\n\n\n-----------------------------\n\n( 1)..مجمع الزوائد ۱/۳۰۴ ،معجم الاوسط ۷/۴۰", "roman": "Tarjuma: Hazrat Jabir bin Abdullah Radiyallahu Anhu farmate hain ke ek Shakhs ne Rasoolullah Sallallahu Alaihi Wasallam se Namaz ke auqaat ke muta'alliq Sawaal kiya. To jab aaftab dhal gaya to Bilal Radiyallahu Anhu ne Zuhr ki azaan di, us ke baad Aap Sallallahu Alaihi Wasallam ne Hukm diya to us ne Takbeer kahi to Aap ne Namaz parhi. Us ne Asr ki azaan us waqt kahi jab ke hum ne samjha ke aadmi ka saya us se barh gaya hai. Us ke baad Aap Sallallahu Alaihi Wasallam ne Hukm diya to unhon ne Takbeer kahi to Aap Sallallahu Alaihi Wasallam ne Namaz parhi, phir Namaz-e-Maghrib ki azaan us waqt di jabke aaftab ghuroob ho gaya. Us ke baad Aap Sallallahu Alaihi Wasallam ne use Hukm diya to us ne Takbeer kahi to Aap Sallallahu Alaihi Wasallam ne Namaz-e-Maghrib parhi. Phir Isha ki azaan us waqt di jabke din ki sufaidi ya'ni shafaq jaati rahi to Aap Sallallahu Alaihi Wasallam ne Hukm diya. Us ne Takbeer kahi to Aap Sallallahu Alaihi Wasallam ne Namaz-e-Isha parhi, phir Fajr ki azaan di, us ke baad Aap Sallallahu Alaihi Wasallam ne Hukm diya to unhon ne Takbeer kahi to Aap Sallallahu Alaihi Wasallam ne Namaz parhi. Phir agle din Bilal Radiyallahu Anhu ne Zuhr ki azaan us waqt di jabke aaftab dhal gaya. To Aap Sallallahu Alaihi Wasallam ne yahan tak takheer ki ke har shai ka saya us ke barabar ho gaya. Us ke baad Aap Sallallahu Alaihi Wasallam ne Hukm diya to us ne Takbeer kahi to Aap Sallallahu Alaihi Wasallam ne Namaz parh li. Phir us ne Asr ki azaan di to Aap Sallallahu Alaihi Wasallam ne yahan tak takheer ki ke har shai ka saya us ke do misl ya'ni dugna ho gaya. To Aap Sallallahu Alaihi Wasallam ne amr kiya (Hukm diya) to us ne Takbeer kahi to Aap Sallallahu Alaihi Wasallam ne Namaz parh li. Phir us ne Maghrib ki azaan us waqt di jabke sooraj ghuroob ho gaya to Aap Sallallahu Alaihi Wasallam ne yahan tak takheer farmaee ke din ki sufaidi ghayab hone ke qareeb ho gayi aur woh shafaq hai. Phir Aap Sallallahu Alaihi Wasallam ne un ko Hukm diya to unhon ne Takbeer kahi to Aap Sallallahu Alaihi Wasallam ne Namaz parhi, phir Isha ki azaan us waqt di jab shafaq ya'ni din ki sufaidi ghayab ho gayi, phir hum so gaye phir jaage. Kai baar aisa hua. Phir Rasoolullah Sallallahu Alaihi Wasallam hamare paas tashreef laye aur farmaya ke tumhare siwa koi aadmi is Namaz ka intezar nahin kar raha. Pas tum Namaz mein hi ho jab tak Namaz ke intezar mein raho. Agar yeh baat na hoti ke main takheer ka Hukm kar ke apni ummat ko mashaqqat mein daal doonga to is Namaz ko nisf shab ya qareeb nisf shab tak takheer ka Hukm deta. Phir unhon ne Fajr ki azaan di to Aap Sallallahu Alaihi Wasallam ne yahan tak takheer ki ke aaftab qareeb-e-tuloo tha. To Aap Sallallahu Alaihi Wasallam ne amr farmaya to unhon ne Takbeer kahi to Aap Sallallahu Alaihi Wasallam ne Namaz-e-Fajr parhi. Phir farmaya ke waqt in dono waqton ke darmiyan hai. Is ko Tabarani ne Awsat mein Riwayat kiya. (1)\n\n-----------------------------\n\n(1).. Majma-uz-Zawaid 1/304, Mu'jam-ul-Awsat 7/40"}, {"id": 6302, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 8, "arabic": "عَنْ اَبِيْ سَعِیْدٍ قَالَ صَلَّیْنَا مَعَ رَسُوْلِ اﷲِ صَلَّی اللہُ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ صَلوٰۃَ الْعَتَمَۃِ فَلَمْ یَخْرُجْ حَتّیٰ مَضٰی نَحْوٌ مِنْ شَطْرِ اللَّیْلِ فَقَالَ خُذُوْا مَقَاعِدَکُمْ فَأَخَذْنَا مَقَاعِدَنَا فَقَالَ إِنَّ النَّاسَ قَدْ صَلُّوْا وَاَخَذُوْا مَضَاجِعَھُمْ وَإِنَّکُمْ لَمْ تَزَالُوْا فِيْ صَلوٰۃٍ مَا انْتَظَرْتُمْ لِصَّلوٰۃِ وَلَوْ لَا ضُعْفُ الضَّعِیْفِ وَسُقْمُ السَّقِیْمِ لَأَخَّرْنَا ھِذِہٖ الصَّلوٰۃَ إِلیٰ شَطْرِ اللَّیْلِ ۔ رَوَاہٗ اَبُو دَاؤُدَ وَ النِّسَائِيُّ وَ ابْنُ مَاجَہْ ۔(السنن ابو داؤد ۱؍۱۱۶ ، النسائی ۱؍۲۲۸،سنن ابن ماجہ ۱؍۳۸۱۔ )", "urdu": "حضرت سیدنا ابو سعید خدری رضی اﷲ عنہ سے روایت ہے ۔ کہا انہوں نے کہ ہم نے رسول کریم صلّی اﷲ علیہ واٰلہٖ وسلّم کے ساتھ نماز پڑھی عشاء کی یعنی کئی راتوں میں اور ایک رات آپ نہ نکلے یہاں تک کہ قریب آدھی رات کے گزر گئی۔ یا یہ کہ ہم نے عشاء پڑھنے کا ارادہ کیا یا یہ کہ ہم نے عشاء پڑھی جس کی تفصیل یہ کہ آپ نہ نکلے یہاں تک کہ تقریباً آدھی رات گزر گئی۔ پھر آپ صلّی اﷲ علیہ واٰلہٖ وسلّم تشر یف لائے اور فرمایا کہ اپنی جگہ بیٹھے رہو۔ ہم اپنی اپنی جگہ پر بیٹھے رہے تو آپ نے فرمایا کہ اور لوگ نماز پڑھ چکے اور اپنی خوابگاہوں میں لیٹ چکے اور تم جب سے نماز کے انتظار میں ہو نماز میں ہی ہو۔اگرمجھے ضعفِ ضعیف (بوڑھوں کی ناتوانی)اور مرضِ مریض کا خیال نہ ہوتا تو میں اس نماز کو نصف شب تک مؤخر کر دیتا۔\nاس حدیث کو ابوداؤد، نسائی اور ابن ماجہ نے روایت کیا ۔", "roman": "Hazrat Sayyiduna Abu Saeed Khudri Radiyallahu Anhu se Riwayat hai. Kaha unhon ne ke hum ne Rasool-e-Kareem Sallallahu Alaihi Wasallam ke sath Namaz parhi Isha ki ya'ni kai raaton mein aur ek raat Aap na nikle yahan tak ke qareeb aadhi raat ke guzar gayi. Ya yeh ke hum ne Isha parhne ka irada kiya ya yeh ke hum ne Isha parhi jis ki tafseel yeh ke Aap na nikle yahan tak ke taqreeban aadhi raat guzar gayi. Phir Aap Sallallahu Alaihi Wasallam tashreef laaye aur farmaya ke apni jagah baithe raho. Hum apni apni jagah par baithe rahe to Aap ne farmaya ke aur log Namaz parh chuke aur apni khwabgahon mein leit chuke aur tum jab se Namaz ke intezar mein ho Namaz mein hi ho. Agar mujhe zo'f-e-Zaeef (boorhon ki natawani) aur maraz-e-mareez ka khayal na hota to main is Namaz ko nisf shab tak mu'akhkhar kar deta.\nIs Hadees ko Abu Dawood, Nasa'i aur Ibn Majah ne Riwayat kiya."}, {"id": 6303, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 9, "arabic": "عَنْ اَبِيْ قَتَادَۃَ قَالَ :قَالَ رَسُوْلُ اﷲِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم اَمَا اَنَّہ ‘لَیْسَ فِيْ النَّوْمِ تَفْرِیْطٌ اِنّمَا التَّفْرِیْطُ عَلَی مَنْ لَّمْ یُصَلِّ حَتَّی یَجِیْئَ وَقْتُ صَلوٰۃِ الْاُخْرٰی۔ رَوَاہٗ مُسْلِمٌ. (الصحیح لِمُسلم ۱/۴۷۳،اَلْسُّنَنْ لِبَیْھَقِیْ اَلْکُبْریٰ ۱/۳۷۶، السنن لابی داؤد ۱/۶۴ )", "urdu": "سرور دوعالم صلّی اﷲ علیہ واٰلہٖ وسلّم نے فرمایا کہ سوجانے میں تفریط نہیں (1 )۔تفریط (یعنی جرم ) اس پر ہے جو نہ نماز پڑھے یہاں تک کہ دوسری نماز کا وقت آجائے ۔اس کو مسلم نے روایت کیا ۔ \n--------------------------------\n(1 ).. حکیم الامت مفتی احمد یار خان نعیمی علیہ الرحمۃ فرماتے ہیں ’’ اگر نماز کے وقت اتفاقا آنکھ نہ کھلے اور نماز قضا ہو جائے تو گناہ نہیں، گناہ تو اس میں ہے کہ انسان جاگتا رہے اور دانستہ نماز قضا کر دے خیال رہے کہ وقت پر آنکھ نہ کھلنا اگر اپنی کوتاہی کی وجہ سے ہو، گناہ ہے، جیسے رات کو بلا وجہ دیر سے سونا جس سے دن چڑھے آنکھ کھلے یقینا جرم ہے۔ (مراۃ المناجیح، ۱/۳۶۳)", "roman": "Sarwar-e-Do Aalam Sallallahu Alaihi Wasallam ne farmaya ke so jaane mein tafreet nahin (1). Tafreet (ya'ni jurm) us par hai jo na Namaz parhe yahan tak ke doosri Namaz ka waqt aa jaaye. Is ko Muslim ne Riwayat kiya.\n--------------------------------\n(1).. Hakeem-ul-Ummat Mufti Ahmad Yar Khan Naeemi Alaihir Rahmah farmate hain 'Agar Namaz ke waqt ittefaqan aankh na khule aur Namaz Qaza ho jaaye to gunah nahin, gunah to us mein hai ke insan jaagta rahe aur danista Namaz Qaza kar de. Khayal rahe ke waqt par aankh na khulna agar apni kotahi ki wajah se ho, gunah hai, jaise raat ko bila wajah der se sona jis se din charhe aankh khule yaqeenan jurm hai.' (Mir'at-ul-Manajeeh, 1/363)"}, {"id": 6304, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 10, "arabic": "عَنْ اَبِیْ وَائِلٍ شَقِیْقِ بْنِ سَلَمَۃَ قَالَ شَھِدْتُّ عَلِیَّ ابْنِ أَبِيْ طَالِبٍ وَ عُثْمَانَ بْنِ عَفَّانَ تَوَضَّاَ ثَلاثًا ثَلاثًا وَ اَفْرَدَ الْمَضْمَضَۃَ مِنَ الْاِسْتِنْشَاقِ ثُمَّ قَالَا ھٰکَذَا رَاَیْنَا رَسُوْلَ اﷲِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم تَوَضَّأَ ۔ رَوَاہٗ عَلِیُّ بْن السَّکَنِ فِي صِحَاحِہِ ، آثَارُالسُّنَنِ. (تَلْخِیْصُ الْحَبِیْرِ۱/۷۹، اَلْاَحَادِیْثُ الْمُخْتَارَہْ۱ /۵۷۲۔ )", "urdu": "حضرت ابووائل شقیق بن سلمہ رضی اﷲ عنہ کہتے ہیں کہ میں حضرت سیدنا علی اور حضرت سیدنا عثمان رضی اﷲ عنہما کے پاس حاضر ہوا ان دونوں نے تین تین بار وضو کے اعضاء کو دھویا اور کلی کو ناک میں پانی ڈالنے سے علیٰحدہ کیا۔ پھر فرمایا کہ ہم نے رسول کریم صلّی اﷲ علیہ واٰلہٖ وسلّم کو اسی طرح وضو کرتے دیکھا ۔\nاس حدیث کو ابن السکن نے اپنی صحاح میں روایت کیا ۔", "roman": "Hazrat Abu Wa'il Shaqeeq bin Salamah Radiyallahu Anhu kehte hain ke main Hazrat Sayyiduna Ali aur Hazrat Sayyiduna Usman Radiyallahu Anhuma ke paas hazir hua, un dono ne teen teen baar Wazu ke aaza ko dhoya aur kulli ko naak mein paani daalne se alahidah kiya. Phir farmaya ke hum ne Rasool-e-Kareem Sallallahu Alaihi Wasallam ko isi tarah Wazu karte dekha.\nIs Hadees ko Ibn-us-Sakan ne apni Sihah mein Riwayat kiya."}, {"id": 6305, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 11, "arabic": "عَنْ اِبْنِ عُمَرَ أَنَّ النَّبِيَّ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم قَالَ مَنْ تَوَضَّأَوَمَسَحَ بِیَدَیْہِ عَلیٰ عُنُقِہٖ وَقَی الْغُلَّ یَوْمَ الْقِیَامَۃِ۔رَوَاہٗ اَبُو الْحَسَنِ بْنِ فَارِسٍ بِاَسْنَادِہٖ وَ قَالَ ھٰذَا اِنْ شَاءَ اﷲ تَعَالیٰ حَدِیْثٌ صَحِیْحٌ۔ (تَلْخِیْصُ الْحَبِیْرِ ۱؍۹۳۔)", "urdu": "حضرت ابن عمر رضی اﷲ عنہ کہتے ہیں کہ رسول کریم ،رؤف رحیم صلّی اﷲ علیہ واٰلہٖ وسلّم نے فرمایا جو شخص وضو کرے اور اپنے دونوں ہاتھوں سے گردن کا مسح کرے وہ قیامت کے دن طوق سے محفوظ رکھا جائے گا ۔", "roman": "Hazrat Ibn Umar RadiyAllahu Anhu kehte hain ke Rasool-e-Kareem, Raoof-o-Raheem Sallallahu Alaihi Wasallam ne farmaya jo Shakhs Wazu kare aur apne dono haathon se gardan ka Masah kare woh Qayamat ke din tauq se mehfooz rakha jaye ga."}, {"id": 6306, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 12, "arabic": "عَنْ عَائِشَۃَ رَضِيَ اﷲ ُ تَعَالیٰ عَنْھَا قَالَتْ قَالَ رَسُوْلُ اﷲِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم مَنْ اَصَابَہٗ قَیْئٌ أَوْ رُعَافٌ أَوْ قَلْسٌ أَوْمَذْيٌ فَلْیَنْصَرِفْ فَلْیَتَوَضَّاْ ثُمَّ لِیَبْنِ عَلیٰ صَلَوٰتِہٖ وَھُوَ فِيْ ذٰلِکَ لَایَتَکَلَّمْ۔ رَوَاہُ ابْنُ مَاجَهْ۔", "urdu": "حضرت سَیِّدَتُنَاعائشہ رَضِیَ اﷲ تَعَالٰی عَنْہَا سے روایت ہے فرمایارسول کریم صلّی اﷲ علیہ واٰلہٖ وسلّم نے جس شخص کوقے یانکسیریاقلس(منہ بھرقے) آجاوے یا مذی نکلے تو وہ نماز سے ہٹ جائے پھر وضو کرے پھر اپنی نماز پر بناکرے اور اس کے درمیان کلام نہ کرے ۔ (1 )اس کو ابن ماجہ نے روایت کیا ۔\n\n\n--------------------------\n(1 )..سنن ابن ماجہ ۔ باب ماجاء فی البناء علی الصّلوۃص۶۹۔", "roman": "Hazrat Sayyidatuna Aisha Radiyallahu Anha se Riwayat hai farmaya Rasool-e-Kareem Sallallahu Alaihi Wasallam ne jis Shakhs ko qay ya nakseer ya qalas (munh bhar qay) aa jawe ya Mazi nikle to woh Namaz se hat jaye phir Wazu kare phir apni Namaz par bina kare aur us ke darmiyan kalaam na kare. (1) Is ko Ibn Majah ne Riwayat kiya.\n\n\n--------------------------\n(1).. Sunan Ibn Majah. Baab Ma Jaa Fil Bina Alas Salah, Safha 69."}, {"id": 6307, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 13, "arabic": "عَنْ طَلَقِ بْنِ عَلِيٍ قَالَ سُئِلَ رَسُوْلُ اﷲِصَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم عَنْ مَسِّ الرَّجُلِ ذَکَرَہٗ بَعْدَ مَا یَتَوَضَّاُ قَالَ وَھَلْ ھُوْ إِلَّا بِضْعَۃٌ مِّنْہُ ۔ رَوَاہٗ اَبُو دَاؤُد وَ التِّرْمِذِیْ وَالنِّسَائِیْ. (السنن لِابو داؤد ۔ باب الوضؤ من مس الذکر ۱؍۹۴ جامع الترمذی ۱؍۱۴۲، النسائی ۱؍۱۰۱۔ )", "urdu": "طلق بن علی کہتے ہیں کہ رسول کریم صلّی اﷲ علیہ واٰلہٖ وسلّم سے پوچھا گیا کہ کوئی شخص وضو کرکے اپنے ذَکر کو مس کرے(آگے کی شرم گاہ کو چھوئے) (تو کیا حکم ہے ؟ ) تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے فرمایا کہ نہیں وہ مگر ایک ٹکڑا اس سے ۔", "roman": "Talq bin Ali kehte hain ke Rasool-e-Kareem Sallallahu Alaihi Wasallam se poocha gaya ke koi Shakhs Wazu karke apne zakar ko mas kare (aage ki Sharm gaah ko chuye) (to kya Hukm hai?) to Aap Sallallahu Alaihi Wasallam ne farmaya ke nahin woh magar ek tukda us se."}, {"id": 6308, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 14, "arabic": "عَنْ جَابِرٍ عَنِ النَّبِيِّ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم قَالَ اَلتَّیَمُّمُ ضَرْبَۃٌ لِلْوَجْہِ وَضَرْبَۃٌ لِلذِّرَاعَیْنِ إِلیٰ الْمِرْفَقَیْنِ۔ رَوَاہٗ الْحَاکِمُ وَ صَحَّحَہٗ وَ قَالَ الدَّارَ قُطْنِیْ رِجَالُہٗ کُلُّھُمْ ثِقَاتٌ (الدار قطنی۱؍۱۸۱۔ )", "urdu": "حضرت سیدنا جابر رضی اﷲ عنہ کہتے ہیں کہ رسول کریم صلّی اﷲ علیہ واٰلہٖ وسلّم نے فرمایا کہ تیمّم دو ضربیں ہیں ۔ ایک ضرب منہ کے لئے ایک ضرب دونوں ہاتھوں کے لئے کہنیوں تک۔", "roman": "Hazrat Sayyiduna Jabir RadiyAllahu Anhu kehte hain ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke Tayammum do zarbein hain. Ek zarb munh ke liye ek zarb dono haathon ke liye kohniyon tak."}, {"id": 6309, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 15, "arabic": "عَنْ عَبْدِ الرَّحْمٰنِ بْنِ اَبِيْ لَیْلٰی قَالَ حَدَّثَنَا اَصْحَابُ مُحَمَّدٍ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم اَنَّ عَبْدَ اﷲِ بْنَ زَیْدِنِ الْاَنْصَارِيْ جَاءَ إِلَی النَّبِیِّ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم فَقَالَ یَا رَسُوْلَ اﷲِرَاَیْتُ فِي الْمَنَامِ کَانَ رَجُلاً قَامَ وَعَلَیْہِ بُرْدَانِ اَخْضَرَانِ فَقَامَ عَلٰی حَائِطٍ فَأَذَّنَ مَثْنیٰ مَثْنیٰ وَ اَقَامَ مَثْنیٰ مَثْنیٰ ۔ رَوَاہُ ابْنُ اَبِیْ شَیْبَۃَ فِی الْمُصَنَّفِ وَ الْبَیْھَقِیُّ فِی سُنَنِہٖ. ( ابن ابی شیبہ ۱/۱۸۵، السنن البیھقی ۱/۴۲۰۔)", "urdu": "حضرت عبد الرحمن بن ابی لیلیٰ کہتے ہیں کہ رسول کریم صلّی اﷲ علیہ واٰلہٖ وسلّم کے اصحاب نے ہمیں حدیث بیان کی کہ عبد اﷲ بن زید انصاری رضی اﷲ عنہ حضور عَلَیْہِ السَّلام کے پاس آئے اور عرض کی کہ یا رسول اﷲ صلّی اﷲ علیہ واٰلہٖ وسلّم میں نے خواب میں دیکھا ہے گویا ایک شخص کھڑا ہے اور اس پر دو سبز کپڑے ہیں ۔وہ دیوار پر کھڑا ہوا۔اس نے دو دو مرتبہ اذان دی اور دو دو مرتبہ اقامت کہی۔ اس کو ابن ابی شیبہ نے مصنف میں اور بیہقی نے سنن میں روایت کیا۔", "roman": "Hazrat Abdur Rahman bin Abi Laila kehte hain ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ke ashaab ne hamein Hadees bayan ki ke Abdullah bin Zaid Ansari RadiyAllahu Anhu Huzoor Alaihis Salam ke paas aaye aur arz ki ke ya Rasoolallah Sallallahu Alaihi Wasallam main ne khwab mein dekha hai goya ek Shakhs khada hai aur us par do sabz kapde hain. Woh deewar par khada hua, us ne do do martaba Azan di aur do do martaba Iqamat kahi. Is ko Ibn Abi Shaibah ne Musannaf mein aur Baihaqi ne Sunan mein Riwayat kiya."}, {"id": 6310, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 16, "arabic": "عَنْ اَنَسٍ قَالَ کَانَ رَسُوْلُ اﷲِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم إِذَا افْتَتَحَ الصَّلوٰۃَ کَبَّرَ ثُمَّ رَفَعَ یَدَیْہِ حَتّیٰ یُحَاذِيَ إِبْھَامَیْہِ اُذُنَیْہِ ثُمَّ یَقُوْلُ سُبْحَانَکَ اللّٰھُمَّ وَبِحَمْدِکَ وَتَبَارَکَ اسْمُکَ وَتَعَالیٰ جَدُّکَ وَ لاَ إِلٰہَ غَیْرُکَ ۔ رَوَاہٗ الدَّارَقُطْنِیْ وَ قَالَ اِسْنَادُہٗ کُلُّھُمْ ثِقَاتٌ کَذَا فِی الزّیْلَعِیْ. (الدار قطنی ۱؍۳۰۰۔ )", "urdu": "حضرت سیدنا انس رضی اﷲ عنہ فرماتے ہیں کہ رسول کریم صلّی اﷲ علیہ واٰلہٖ وسلّم جب نماز کوشروع کرتے تو تکبیر کہتے پھر دونوں ہاتھوں کو اٹھاتے یہاں تک کہ آپ صلّی اﷲ علیہ واٰلہٖ وسلّم کے انگھوٹھے دونوں کانوں کے برابر ہوجاتے پھر سُبْحَانَک اللّٰھُمَّ آخر تک پڑھتے ۔اس کو دارقطنی نے روایت کیا۔اس کے سب رواۃثقہ ہیں۔", "roman": "Hazrat Sayyiduna Anas RadiyAllahu Anhu farmate hain ke Rasool-e-Kareem Sallallahu Alaihi Wasallam jab Namaz ko shuru karte to Takbeer kehte phir dono haathon ko uthate yahan tak ke Aap Sallallahu Alaihi Wasallam ke anghoothe dono kaanon ke barabar ho jaate phir Subhanakallahumma aakhir tak padhte. Is ko Daraqutni ne Riwayat kiya. Is ke sab ruwaat Siqqah hain."}, {"id": 6311, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 17, "arabic": "عَنْ وَائِلِ بْنِ حَجَرٍ قَالَ رَأَیْتُ النَّبِیَّ صَلَّی اللہُ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم وَضَعَ یَمِیْنَہٗ عَلیٰ شِمَالِہٖ فِيْ الصَّلوٰۃِ تَحْتَ السُّرَّۃِ۔ \n(اَخْرَجَہٗ ابْنُ اَبِیْ شِیْبَۃَ فِی الْمُصَنَّفِ۱ / ۳۹۰ ، تَدْرِیْبُ الرَّاوِیْ ۱ / ۱۸۸ آثَارُ السُّنَنِ ۱۷", "urdu": "حضرت وائل بن حجر کہتے ہیں کہ میں نے دیکھا رسول کریم صلّی اﷲ علیہ واٰلہٖ وسلّم کو کہ آپ نے نماز میں دایاں ہاتھ بائیں پر ناف کے نیچے رکھا ۔ اس کو ابن ابی شیبہ نے روایت کیا۔", "roman": "Hazrat Wail bin Hujr kehte hain ke main ne dekha Rasool-e-Kareem Sallallahu Alaihi Wasallam ko ke Aap ne Namaz mein daayan haath bayen par Naaf ke neeche rakha. Is ko Ibn Abi Shaibah ne Riwayat kiya."}, {"id": 6312, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 18, "arabic": "عَنْ حُمَیْدِ الطَّوِیْلِ عَنْ أَنَسِ بْنِ مَالِکٍ قَالَ کَانَ رَسُوْلُ اﷲِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم اِذَ اسْتَفْتَحَ الصَّلوٰۃَ قَالَ سُبْحَانَکَ اللَّھُمَّ وَبِحَمْدِکَ وَتَبَارَکَ اسْمُکَ وَ تَعَالٰی جَدُّکَ وَلَا اِلٰہَ غَیْرُکَ رَوَاہُ الطَّبْرَانِیْ فِیْ کِتَابِہِ الْمُفْرَدِ فِیْ الدُّعَاءِ وَ اِسْنَادُہٗ جَیِّدَۃٌ . ( آثَارَ السُّنَنْ ،نصب الرایۃ۱/۳۲۱ )", "urdu": "حضرت سیدنا اَنَس رضی اﷲ عنہ فرماتے ہیں کہ رسول کریم صلّی اﷲ علیہ واٰلہٖ وسلّم جب نماز شروع کرتے تو سُبْحَانَکَ اللّٰھُمَّ اِلٰی آخِرِہٖ پڑھتے ۔ اس کو طبرانی نے روایت کیا۔", "roman": "Hazrat Sayyiduna Anas RadiyAllahu Anhu farmate hain ke Rasool-e-Kareem Sallallahu Alaihi Wasallam jab Namaz shuru karte to Subhanakallahumma ila aakhirihi padhte. Is ko Tabarani ne Riwayat kiya."}, {"id": 6313, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 19, "arabic": "عَنْ أَنَسٍ أَنَّ النَّبِیَّ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم وَأَبَابَکْرٍ وَ عُمَرَ کَانُوْا یَفْتَتِحُوْنَ الصَّلوٰۃَ بِالْحَمْدُ لِلّٰہِ رَبِّ الْعٰلَمِیْنَ۔ رَوَاہٗ الشَّیْخَانِ ( صحیح البخاری،کتاب الاذان ۱/۱۰۳،الصحیح لمسلم۱/۱۷۲)", "urdu": "حضرت سیدنا اَنَس رضی اﷲ عنہ فرماتے ہیں کہ رسول کریم صلّی اﷲ علیہ واٰلہٖ وسلّم اور حضرت سیدنا ابوبکر صدیق و سیدنا عمربن خطاب رضی اﷲ عنہما نماز اَلْحَمْدُلِلّٰہِ رَبِّ الْعٰلَمِیْنَ کے ساتھ شروع کرتے تھے۔", "roman": "Hazrat Sayyiduna Anas RadiyAllahu Anhu farmate hain ke Rasool-e-Kareem Sallallahu Alaihi Wasallam aur Hazrat Sayyiduna Abu Bakr Siddiq wa Sayyiduna Umar bin Khattab Radiyallahu Anhuma Namaz Alhamdulillahi Rabbil Aalameen ke saath shuru karte the."}, {"id": 6314, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 20, "arabic": "عَنْ اَبِیْ مُوْسیٰ قَالَ عَلَّمَنَا رَسُوْلُ اﷲِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم قَالَ اِذَا قُمْتُمْ اِلَی الصَّلوٰۃِ فَلْیَؤُمُّکُمْ أحَدُکُمْ وَاِذَا قَرَأَ الْاِمَامُ فَاَنْصِتُوْا۔رَوَاہُ أَحْمَدُ وَ مُسْلِمٌ ( الصحیح لمسلم،۱/۱۷۴ اَلدِّرَایَۃُ فِیْ تَخْرِیْجِ اَحَادِیْثِ الھِدَایَۃِ ۱/۱۶۴، مُسْنَدُ اَبِیْ عَوَانَہ۲/۱۳۳۔)", "urdu": "حضرت سیدنا ابو موسیٰ اشعری رضی اﷲ عنہ کہتے ہیں کہ رسول کریم و رؤف رحیم صلّی اﷲ علیہ واٰلہٖ وسلّم نے ہمیں سکھایا کہ جب تم نماز کے لئے اٹھو تو چاہیئے کہ تم میں سے ایک تمہارا امام بنے اور جب امام پڑھے تو تم چپ رہو ۔\nاس کو امام احمدومسلم نے روایت کیا۔", "roman": "Hazrat Sayyiduna Abu Moosa Ash'ari RadiyAllahu Anhu kehte hain ke Rasool-e-Kareem wa Raoof-o-Raheem Sallallahu Alaihi Wasallam ne hamein sikhaya ke jab tum Namaz ke liye utho to chahiye ke tum mein se ek tumhara Imam bane aur jab Imam padhe to tum chup raho.\nIs ko Imam Ahmad wa Muslim ne Riwayat kiya."}, {"id": 6315, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 21, "arabic": "عَنْ جَابِرٍ قَالَ قَالَ رَسُوْلُ اﷲِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم مَنْ کَانَ لَہٗ اِمَامٌ فَقِرَاءَۃُ الْاِمَامِ لَہٗ قِرَاءَۃٌ۔ رَوَاہٗ الْحَافِظُ اَحْمَدُ بْنُ مُنِیْعٍ فِیْ مُسْندِہِ وَ مُحَمَّدٌ فِی الْمُؤَطَّا وَ الطَّحَاوِیْ وَ الدَّارَقُطْنِیْ ( المؤطا لامام محمد ۸۹ ، المسند لامام اعظم ۶۱۔)", "urdu": "حضرت سیدنا جابر رضی اﷲ عنہ سے روایت ہے کہ رسول کریم صلّی اﷲ علیہ واٰلہٖ وسلّم نے فرمایا جس شخص کے لئے امام ہو تو امام کا پڑھنا اسی کا پڑھنا ہے ۔", "roman": "Hazrat Sayyiduna Jabir Radiyallahu Anhu se Riwayat hai ke Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya: Jis Shakhs ke liye Imam ho to Imam ka parhna usi ka parhna hai."}, {"id": 6316, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 22, "arabic": "عَنْ اَبِیْ ھُرَیْرَۃَ اَنَّ رَسُوْلَ اﷲِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم قَالَ اِذَا قَالَ الْاِمَامُ غَیْرِالْمَغْضُوْبِ عَلَیْھِمْ وَلَاالضَّآلِیْنَ فَقُوْلُوْا آمِیْن فَاِنَّہٗ مَنْ وَافَقَ قَوْلَ الْمَلٰئِکَۃِ غُفِرَ لَہٗ مَا تَقَدَّمَ مِنْ ذَنْبِہٖ۔ رَوَاہٗ الْبُخَارِیْ (صحیح البخاری کتاب التفسیر ۴/۱۶۲۳۔)", "urdu": "حضرت سیدنا ابوہریرہ رضی اﷲ عنہ سے روایت ہے کہ رسول کریم ، رؤف رّحیم صلّی اﷲ علیہ واٰلہٖ وسلّم نے فرمایا جب امام غَیْرِ الْمَغْضُوْبِ عَلَیْھِمْ وَ لاَ الضَّالِّیْنَ کہے تو تم آمین کہو ۔ کیونکہ جس کی آمین ملائکہ کی آمین کے ساتھ موافق ہوگئی اس کے پچھلے گناہ معاف ہوگئے۔اس کو بخاری نے روایت کیا۔", "roman": "Hazrat Sayyiduna Abu Hurairah Radiyallahu Anhu se Riwayat hai ke Rasool-e-Kareem, Raoof-ur-Raheem Sallallahu Alaihi Wasallam ne farmaya: Jab Imam 'Ghayril Maghdoobi Alaihim Walad-Daalleen' kahe to tum Aameen kaho. Kyunkay jis ki Aameen Malaika ki Aameen ke saath muwafiq ho gayi us ke pichhle gunah maaf ho gaye. Is ko Bukhari ne Riwayat kiya."}, {"id": 6317, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 23, "arabic": "عَنْ وَائِلِ بْنِ حَجَرٍ أَنَّہٗ مَعَ رَسُوْلِ اﷲِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم فَلَمَّا بَلَغَ غَیْرِ الْمَغْضُوْبِ عَلَیْھِمْ وَلاَ الضَّآلِیْنَ قَالَ اٰمِیْن اَخْفٰی بِھَا صَوْتَہٗ۔ رَوَاہٗ الْحَاکِمُ وَ الطَّبْرَانِیْ وَ الدَّارَقُطْنِیْ وَ اَبُوْ یَعْلٰی وَ اَحْمَدُ (جامع الترمذی۶۳، نصب الرایۃ ۱/۳۶۹۔)", "urdu": "حضرت وائل بن حجر سے روایت ہے کہ انہوں نے رسول کریم صلّی اﷲ علیہ واٰلہٖ وسلّم کے ساتھ نماز پڑھی۔حضور صلّی اﷲ علیہ واٰلہٖ وسلّم جب’’غَیْرِ الْمَغْضُوْبِ عَلَیْھِمْ وَ لاَ الضَّالِّیْن‘‘کو پہنچے تو آپ صلّی اﷲ علیہ واٰلہٖ وسلّم نے پوشیدہ آواز سے آمین کہی ۔\nاس حدیث کو حاکم ،طبرانی ،دارقطنی ، ابو یعلی اور امام احمد نے روایت کیا۔ یہ حدیث آمین کے اخفا میں نص ہے ۔اس کی سند صحیح ہے ۔", "roman": "Hazrat Wail bin Hujr se Riwayat hai ke unhon ne Rasool-e-Kareem Sallallahu Alaihi Wasallam ke saath Namaz parhi. Huzoor Sallallahu Alaihi Wasallam jab 'Ghayril Maghdoobi Alaihim Walad-Daalleen' ko pohanche to Aap Sallallahu Alaihi Wasallam ne posheedah aawaz se Aameen kahi.\nIs Hadees ko Hakim, Tabarani, Daraqutni, Abu Ya'la aur Imam Ahmad ne Riwayat kiya. Yeh Hadees Aameen ke ikhfa mein nass hai. Is ki Sanad Saheeh hai."}, {"id": 6318, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 24, "arabic": "عَنْ جَابِرِ بْنِ سَمُرَۃَ قَالَ خَرَجَ عَلَیْنَا رَسُوْلُ اﷲِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّمَ فَقَالَ مَالِیْ اَرَاکُمْ رَافِعِیْ اَیْدِیَکُمْ کَأَنَّھَا اَذْنَابُ خَیْلٍ شَمْسٍ اُسْکُنُوْا فِی الصَّلوٰۃِ ۔رَوَاہٗ مُسْلِمٌ (الصحیح لمسلم۱ /۱۸۱ ،ابو داود۱ /۱۴۳۔)", "urdu": "حضرت جابر بن سمرہ رضی اﷲ عنہ سے روایت ہے کہا انہوں نے نکلے ہم پر رسول کریم صلّی اﷲ علیہ واٰلہٖ وسلّم اور فرمایا کیا ہے مجھے کہ میں تمہیں رفع یدین کرتا ہوا دیکھتا ہوں گویا کہ سرکش گھوڑوں کی دم ہیں ۔ نماز میں آرام کیا کرو ۔اس کو مسلم نے روایت کیا۔", "roman": "Hazrat Jabir bin Samurah Radiyallahu Anhu se Riwayat hai, kaha unhon ne: Nikle hum par Rasool-e-Kareem Sallallahu Alaihi Wasallam aur farmaya: Kya hai mujhe ke main tumhein Rafa-e-Yadain karta hua dekhta hoon goya ke sarkash ghoron ki Damm hain. Namaz mein aaram kiya karo. Is ko Muslim ne Riwayat kiya."}, {"id": 6319, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 25, "arabic": "عَنْ عَلْقَمَۃَ قَالَ قَالَ عَبْدُ اﷲِ بْنُ مَسْعُودٍرَضِیَ اﷲ تَعَالٰی عَنْہُ اَلا أُصَلِّيْ بِکُمْ صَلوٰۃَ رَسُوْلِ اﷲِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم فَصَلَّی وَلَمْ یَرْفَعْ یَدَیْہِ إِلَّا مَرَّۃً ۔ اَبُوْ دَاوٗدَ (١٠٤ابوداؤد ۱؍۱۰۹، جامع ا لترمذی ۲؍۴۰، النسائی ۱؍۱۹۵۔ )", "urdu": "حضرت علقمہ رضی اﷲ عنہ کہتے ہیں کہ عبد اﷲ بن مسعودرضی اﷲ عنہ نے فرمایا کہ میں تمہیں رسول اﷲ صلّی اﷲ علیہ واٰلہٖ وسلّم کی نماز پڑھ کرنہ دکھاؤں ؟ پھر نماز پڑھی اور ایک بار (تحریمہ ) کے سوا ہاتھ نہ اٹھائے۔اس حدیث کو ابوداؤد، ترمذی و نسائی نے روایت کیا۔", "roman": "Hazrat Alqamah Radiyallahu Anhu kehte hain ke Abdullah bin Mas'ood Radiyallahu Anhu ne farmaya: Kya main tumhein Rasoolullah Sallallahu Alaihi Wasallam ki Namaz parh kar na dikhaun? Phir Namaz parhi aur ek baar (Tahreemah) ke siwa haath na uthaye. Is Hadees ko Abu Dawood, Tirmizi wa Nasai ne Riwayat kiya."}, {"id": 6320, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 26, "arabic": "عَنْ اَبِيْ ھُرَیْرَۃَ رَضِیَ اﷲ تَعَالٰی عَنْہُ قَالَ ، قَالَ رَسُوْلُ اﷲ ِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم اِذَا قَالَ الْاِمَامُ سَمِعَ اﷲ ُ لِمَنْ حَمِدَہُ فَقُوْلُوْا اَللّٰھُمَّ رَبَّنَا لَکَ الْحَمْدُ فَإِنَّہٗ مَنْ وَافَقَ قَوْلُه‘ قَوْلَ الْمَلٰئِکَۃِ غُفِرَ لَہٗ مَا تَقَدَّمَ مِنْ ذَنْبِہٖ ۔ مُتَّفَقٌ عَلَیْہِ ( صحیح البخاری ۳؍۱۱۷۹، الصحیح لمسلم ۱؍۳۰۶۔)", "urdu": "حضرت سیدنا ابوہریرہ رَضِیَ اﷲ تَعَالٰی عَنْہُ سے روایت ہے فرمایا رسول کریم صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے جب امام سَمِعَ اﷲ لِمَنْ حَمِدَہٗکہے تو تم اَللّٰھُمَّ رَبَّنَا لَکَ الْحَمْدُکہو ۔بے شک جس شخص کا قول فِرشتوں کے قول کے موافق ہو اس کے اگلے سب گناہ بخشے جاتے ہیں ۔ \nاس کو بخاری و مسلم نے روایت کیا۔", "roman": "Hazrat Sayyiduna Abu Hurairah Radiyallahu Ta'ala Anhu se Riwayat hai, farmaya Rasool-e-Kareem Sallallahu Ta'ala Alaihi Wasallam ne: Jab Imam 'Sami Allahu Liman Hamidah' kahe to tum 'Allahumma Rabbana Lakal Hamd' kaho. Beshak jis Shakhs ka Qaul Farishton ke Qaul ke muwafiq ho us ke agle sab gunah bakhsh diye jaate hain.\nIs ko Bukhari wa Muslim ne Riwayat kiya."}, {"id": 6321, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 27, "arabic": "عَنْ وَائِلِ بْنِ حُجَرٍ قَالَ رَأیْتُ رسول َ ﷲِ صَلَّي اللهُ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم إِذَا سَجَدَ وَضَعَ رُکْبَتَیْہِ قَبْلَ یَدَیْہِ وَ إِذَا نَھَضَ رَفَعَ یَدَیْہِ قَبْلَ رُکْبَتَیْہِ۔ رَوَاہٗ الْاَرْبَعَۃُ وَ ابْنُ خُزَیْمَۃَ وَ ابْنُ حَبَان (جامع الترمذی ۲؍۵۶، ابوداؤد ۱؍۲۲۲، السنن لنسائی ۲؍۲۰۶۔ ، ابن حبان ۳؍۱۹۱۔)", "urdu": "حضرت وائل بن حجر رَضِیَ اﷲ تَعَالٰی عَنْہُ کہتے ہیں کہ میں نے رسول کریم صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کو دیکھا جب سجدہ کرتے اپنے گھٹنوں کو ہاتھوں سے پہلے رکھتے اور جب اٹھتے تو ہاتھوں کو پہلے اٹھاتے ۔", "roman": "Hazrat Wail bin Hujr Radiyallahu Ta'ala Anhu kehte hain ke main ne Rasool-e-Kareem Sallallahu Ta'ala Alaihi Wasallam ko dekha jab Sajdah karte apne ghutnon ko haathon se pehle rakhte aur jab uthte to haathon ko pehle uthate."}, {"id": 6322, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 28, "arabic": "عَنْ عَبَّاسِ بْنِ عَبْدِالْمُطَّلِبِ أنَّہٗ سَمِعَ رَسُوْلَ اﷲ ِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم یَقُوْلُ إِذَا سَجَدَ الْعَبْدُ سَجَدَ مَعَہ‘ سَبْعَۃُ اَرَابٍ وَجْھُہ‘ وَکَفَّاہُ وَ رُکْبَتَاہُ وَقَدَمَاہُ۔ رَوَاہٗ التِّرْمِذِیْ (جامع الترمذی ۲/۶۱ ، البیھقی ۲/۱۰۱۔)", "urdu": "حضرت سیدنا عباس بن عبدالمطلب رَضِیَ اﷲ تَعَالٰی عَنْہُ سے روایت ہے انہوں نے رسول اﷲ عَزَّوَجَلَّ و صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کو سنا فرماتے تھے جب بندہ سجدہ کرتا ہے تو اس کے ساتھ سات اعضاء سجدہ کرتے ہیں ۔ایک منہ اور اس کے دونوں ہاتھ اور دونوں زانواور دونوں قدم ۔اس حدیث کو ترمذی نے روایت کیا اور کہا یہ حدیث حسن صحیح ہے ۔اور اہل علم کا اسی پر عمل ہے ۔", "roman": "Hazrat Sayyiduna Abbas bin Abdul Muttalib Radiyallahu Ta'ala Anhu se Riwayat hai, unhon ne Rasoolullah Azza wa Jall wa Sallallahu Ta'ala Alaihi Wasallam ko suna farmate the: Jab bandah Sajdah karta hai to us ke saath saat a'za Sajdah karte hain. Ek munh aur us ke dono haath aur dono zaanu aur dono qadam. Is Hadees ko Tirmizi ne Riwayat kiya aur kaha yeh Hadees Hasan Saheeh hai. Aur Ahl-e-Ilm ka isi par amal hai."}, {"id": 6323, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 29, "arabic": "اَنَّ رسول اﷲ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم مَرَّ عَلَی امْرَأتَیْنِ تُصَلِّیَانِ فَقَالَ إذَا سَجَدْتُّمَا فَضُمَّا بَعْضَ اللَّحْمِ اِلَی الْاَرْضِ فَأِنَّ الْمَرْأَةَ لَیْسَتْ فِیْ ذٰلِکَ کَرَجُلٍ۔ (المراسیل لابی داؤد ۱؍۱۱۸، تلخیص الحبیر ۱؍۲۴۲، السنن لبیھقی الکبری۲ /۲۲۳)", "urdu": "کہ رسول کریم صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم دو عورتوں پر گزرے جو نماز پڑھ رہی تھیں تو آپ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا إِذَا سَجَدْتُّمَا فَضُمَّا بَعْضَ اللَّحْمِ کہ جب تم سجدہ کرو تو اپنے بعض اعضاء کو زمین کے ساتھ چسپاں کرو۔ یعنی پیٹ رانوں کے ساتھ اور ہاتھ زمین کے ساتھ چمٹ جائیں ۔", "roman": "Ke Rasool-e-Kareem Sallallahu Ta'ala Alaihi Wasallam do Auraton par guzre jo Namaz parh rahi theen to Aap Sallallahu Ta'ala Alaihi Wasallam ne farmaya: 'Iza Sajadtuma Fadumma Ba'dal Lahm' ke jab tum Sajdah karo to apne ba'z a'za ko Zameen ke saath chaspan karo. Ya'ni pait Raanon ke saath aur haath Zameen ke saath chimat jayein."}, {"id": 6324, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 30, "arabic": "عَنْ أَبِيْ ھُرَیْرَۃَ رَضِیَ اﷲ تَعَالٰی عَنْہُ قَالَ کَانَ النَّبیُّ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم یَنْھَضُ فِي الصَّلوٰۃ عَلٰی صُدُوْرِ قَدَمَیْہِ۔رَوَاہٗ التِّرْمِذِیْ ( جامع الترمذی ۲؍۸۰ ۔)", "urdu": "حضرت سیدنا ابوہریرہ رَضِیَ اﷲ تَعَالٰی عَنْہُ کہتے ہیں کہ رسول کریم ،رؤف رّحیم صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نمازمیں اپنے قدموں کے کنارہ پر کھڑے ہوتے تھے۔\nاس کو ترمذی نے روایت کیا۔", "roman": "Hazrat Sayyiduna Abu Hurairah Radiyallahu Ta'ala Anhu kehte hain ke Rasool-e-Kareem, Raoof-ur-Raheem Sallallahu Ta'ala Alaihi Wasallam Namaz mein apne qadmon ke kinarah par khare hote the.\nIs ko Tirmizi ne Riwayat kiya."}, {"id": 6325, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 31, "arabic": "عَنْ وَائِلِ بْنِ حَجَرٍ قَالَ صَلَّیْتُ خَلْفَ رَسُوْلِ اﷲ ِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم فَلَمَّا قَعَدَ وَتَشَھَّدَ فَرَشَ قَدَمَہُ الْیُسْریٰ عَلَی الاَرْضِ وَ جَلَسَ عَلَیْھَا ۔ رَوَاہُ الطَّحَاوِِیْ ( شرح معانی الاثار للطحاوی ۱۸۴ ۔)", "urdu": "حضرت سیدنا وائل رَضِیَ اﷲ تَعَالٰی عَنْہُ کہتے ہیں میں نے رسول کریم صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کے پیچھے نماز پڑھی جب آپ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم بیٹھے اور تشہد پڑھا تو آپ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے بایاں قدم زمین پر بچھایا اور اس پر بیٹھے۔ \nاس کو طحاوی نے روایت کیا ۔", "roman": "Hazrat Sayyiduna Wa'il RadiyAllahu Anhu kehte hain main ne Rasool-e-Kareem Sallallahu Alaihi Wasallam ke peeche Namaz padhi jab Aap Sallallahu Alaihi Wasallam baithe aur Tashahhud padha to Aap Sallallahu Alaihi Wasallam ne bayanya qadam Zameen par bichhaya aur us par baithe.\nIs ko Tahawi ne Riwayat kiya."}, {"id": 6326, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 32, "arabic": "عَنْ عَبْدِ اﷲ بْنِ مَسْعُودٍ قَالَ کُنَّا إِذَا صَلَّیْنَا مَعَ النَّبِیّ صَلَّی اللہُ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم قُلْنَا اَلسَّلاَمُ عَلَی اﷲ ِ قِبَلَ عِبَادِہِ اَلسَّلامُ عَلیٰ جِبْرَائِیْلَ اَلسَّلامُ عَلیٰ مِیْکَائِیْلَ اَلسَّلاَمُ عَلٰی فُلانٍ فَلَمَّا اِنْصَرَفَ النَّبِیُّ صَلَّی اللہُ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم اَقْبَلَ عَلَیْنَا بِوَجْھِہٖ قَالَ لاَ تَقُوْلُوْا اَلسَّلاَمُ عَلَی اللّٰہِ فَإِنَّ اللّٰہَ ھُوَ السَّلاَمُ فَإِذَا جَلَسَ أحَدُکُمْ فِی الصَّلوٰۃِ فَلْیَقُلْ اَلتَّحِیَّاتُ لِلّٰہِ وَالصَّلَوَاۃُ وَالطَّیِّبَاتُ اَلسَّلاَمُ عَلَیْکَ اَیُّھَا النَّبِیُّ وَرَحْمَۃُ اﷲ وَبَرَکَاتُه‘ اَلسَّلاَمُ عَلَیْنَا وَعَلیٰ عِبَادِ اﷲِ الصَّالِحِیْنَ فَإِنَّہٗ إِذَا قَالَ ذٰلِکَ اَصَابَ کُلَّ عَبْدٍ صَالِحٍ فِی السَّمَآءِ وَالْأَرْضِ اَشْھَدُ اَنْ لَّا اِلٰہَ إِلَّا اللّٰہُ وَاَشْھَدُ اَنَّ مُحَمَّدًا عَبْدُہ‘ وَرُسُوْلُہٰ ۔ مُتَّفَقٌ عَلَیْہِ (صحیح البخاری ۱؍۱۱۵،الصحیح لمسلم کتاب الصلوۃ ۱؍۱۷۳ )", "urdu": "حضرت سیدنا عبد اﷲ بن مسعود رَضِیَ اﷲ تَعَالٰی عَنْہُ فرماتے ہیں کہ ہم جب رسول کریم صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کے ساتھ نماز پڑھتے تھے تو کہتے تھے سلام ہو اﷲ عَزَّوَجَلَّ پر سلام ہو جبرائیل عَلَیْہِ السَّلام پر سلام ہو میکائیل عَلَیْہِ السَّلام پر سلام ہو فلاں پر ۔ تو جب رسول کریم صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نماز سے پھرے تو ہماری طرف منہ کرکے فرمایا یہ نہ کہا کرو کہ اﷲ پر سلام ہو کیونکہ اﷲ ہی سلام ہے ۔جب تمہارا کوئی نماز میں بیٹھے تو یہ پڑھے اَلتَّحِیَّاتُ ِﷲِ وَالصَّلَوَاتُ وَالطَّیِّبَاتُ اَلسَّلاَمُ عَلَیْکَ اَیُّھَا النَّبِیُّ وَ رَحْمَۃُ اللّٰہِ وَ بَرَکَاتُہٗ اَلسَّلاَمُ عَلَیْنَا وَ عَلٰی عِبَادِ اللّٰہِ الصَّالِحِیْنَ اَشْھَدُ اَن لاَّ اِلٰہَ اِلاَّ اللّٰہُ وَ اَشْھَدُ اَنَّ مُحَمَّدًا عَبْدُہٗ وَ رَسُوْلُہٗ (1)۔ اس حدیث کو بخاری و مسلم نے روایت کیا۔\n \n(1) ترجمہ: تمام قولی و بدنی اورمالی عبادتیں اﷲ تعالیٰ کیلئے ہیں ۔اے غیب کی خبریں بتانے والے (نبی) صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم آپ پر سلام ہو اور اﷲ تعالیٰ کی رحمتیں اور برکتیں نازل ہوں، ہم پر سلام ہو اور اﷲ تعالیٰ کے نیک بندوں پر ، میں گواہی دیتا ہوں کہ اﷲ تعالیٰ کے سوا کوئی عبادت کے لائق نہیں میں گواہی دیتا ہوں کے بیشک محمد صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم اﷲ تعالیٰ کے بندے اور اس کے رسول ہیں ۔", "roman": "Hazrat Sayyiduna Abdullah bin Mas'ood RadiyAllahu Anhu farmate hain ke hum jab Rasool-e-Kareem Sallallahu Alaihi Wasallam ke saath Namaz padhte the to kehte the Salam ho Allah Azza wa Jall par, Salam ho Jibraeel Alayhis Salam par, Salam ho Mikaeel Alayhis Salam par, Salam ho falaan par. To jab Rasool-e-Kareem Sallallahu Alaihi Wasallam Namaz se phire to hamari taraf munh karke farmaya yeh na kaha karo ke Allah par Salam ho kyonke Allah hi Salam hai. Jab tumhara koi Namaz mein baithe to yeh padhe: \"At-tahiyyatu lillahi was-salawatu wat-tayyibatu, as-salamu 'alayka ayyuhan-nabiyyu wa rahmatullahi wa barakatuh, as-salamu 'alayna wa 'ala 'ibadillahis-saliheen, ash-hadu al-la ilaha illallahu wa ash-hadu anna Muhammadan 'abduhu wa rasooluh\" (1). Is Hadees ko Bukhari wa Muslim ne Riwayat kiya.\n\n(1) Tarjuma: Tamam qauli wa badani aur Maal-i ibadatein Allah Ta'ala ke liye hain. Aye ghayb ki khabrein batane wale (Nabi) Sallallahu Alaihi Wasallam Aap par Salam ho aur Allah Ta'ala ki rahmatein aur barkatein nazil hon, hum par Salam ho aur Allah Ta'ala ke nek bandon par, main Gawahi deta hoon ke Allah Ta'ala ke siwa koi ibadat ke laaiq nahi, main Gawahi deta hoon ke beshak Muhammad Sallallahu Alaihi Wasallam Allah Ta'ala ke bande aur us ke Rasool hain."}, {"id": 6327, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 33, "arabic": "إِذَا شَکَّ أَحَدُکُمْ فِیْ صَلَاتِہٖ فَلْیَتَحَرَّ الصَّوَابَ فَلْیُتِمَّ عَلَیْہِ ثُمَّ یُسَلِّمُ ثُمَّ سَجَدَ سَجْدَتَیْنِ ۔ مُتَّفَقٌ عَلَیْہِ (الصحیح لمسلم،کتاب المساجد ۱؍۲۱۲۔)", "urdu": "حضرت سیدنا عبد اﷲ بن مسعود رَضِیَ اﷲ تَعَالٰی عَنْہُ سے روایت ہے فرمایا رسول کریم صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے : جب کسی کو نماز میں شک ہو تو صواب کا قصدکرے اور اس پر پورا کرے پھر سلام کہے اور دو سجدے (سہو کے) کرے۔", "roman": "Hazrat Sayyiduna Abdullah bin Mas'ood RadiyAllahu Anhu se Riwayat hai farmaya Rasool-e-Kareem Sallallahu Alaihi Wasallam ne: Jab kisi ko Namaz mein shak ho to sawab ka qasd kare aur us par poora kare phir Salam kahe aur do sajde (sahw ke) kare."}, {"id": 6328, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 34, "arabic": "عَنْ اَبِی اُمَامَۃَ قَالَ قِیْلَ یَا رسول اﷲ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم اَیُّ الدُّعَاءِ اَسْمَعُ؟قَالَ جَوْفَ اللَّیْلِ الْاٰخِرِ وَ دُبُرَالصَّلَوَاتِ الْمَکْتُوْبَاتِ (جامع الترمذی ۵۱۳ ،عمل الیوم واللیلہ ۱؍۱۸۶۔)", "urdu": "حضرت سیدنا ابو امامہ رَضِیَ اﷲ تَعَالٰی عَنْہُ کہتے ہیں کہا گیا یا رسول اﷲ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کونسی دعا زیادہ سنی جاتی ہے ۔ فرمایا پچھلی رات کے درمیان اور فرض نمازوں کے بعد ۔اس کو ترمذی نے روایت کیا۔", "roman": "Hazrat Sayyiduna Abu Umamah RadiyAllahu Anhu kehte hain kaha gaya ya Rasoolallah Sallallahu Alaihi Wasallam kaunsi Dua zyada suni jaati hai. Farmaya pichhli raat ke darmiyan aur Farz namazon ke baad. Is ko Tirmizi ne Riwayat kiya."}, {"id": 6329, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 35, "arabic": "مَا مِنْ عَبْدٍ بَسَطَ کَفَّیْہِ فِیْ دُبُرِِکُلِّ صَلوٰۃٍ ثُمَّ یَقُوْلُ اَللّٰھُمَّ إِلٰھِیْ وَإِلٰہَ إِبْرَاھِیْمَ وَإِسْحَاقَ وَیَعْقُوْبَ وَإِلٰہَ جِبْرِِیْلَ وَمِیْکَائِیْلَ وَ إِسْرَافِیْلَ اَسْئَلُکَ اَنْ تَسْتَجِیْبَ دَعْوَتِیْ فَإِنِّیْ مُضْطَرٌّ وَ تَعْصِمَنِيْ فِیْ دِیْنِیْ فَإِنِّیْ مُبْتَلًی وَتَنَالَنِیْ بِرَحْمَتِکَ فَإِنِّیْ مُذْنِبٌ وَتَنْفِی عَنِّی الْفَقْرَ فَإِنِّیْ مُتَمَسْکِنٌ إِلَّا کَانَ حَقًّا عَلَی اﷲ ِ عَزَّوَجَلَّ اَنْ لاَّ یَرُدَّ یَدَیْہِ خَائِبَیْنِ ۔ ( تُحْفَۃُ الْاَحْوَذِیْ ۲؍۱۷۱۔)", "urdu": "رسول کریم صَلَّی اﷲتَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا یعنی جو شخص ہرنمازکے پیچھے (بعد) ہاتھ پسار (پھیلا )کر یہ دعا پڑھے تواﷲ تبار ک وتعا لیٰ پرحق ہے کہ وہ اس کے ہاتھ خالی نہ پھیرے ۔اس حدیث کو حافظ ابوبکر بن السنی نے عمل الیوم واللیلۃ میں روایت کیا۔\n\n\n------------\n(1).. ترجمہ :اے اﷲ! اے میرے معبود اور اے ابراہیم و اسحٰق اور یعقوب علیہم الصلٰوۃوالسلام کے خدا اور اے جبرائیل و میکائیل اور اسر افیل علیہم السلام کے رب د! مجھ لاچار کی دعا قبول فرما،اور میں مبتلائے مشکلات ہوں ، میرے دین میں میری حفاظت فرما ، اورمجھ گناہگار پراپنی رحمت نازل فرما اور مجھ سے مفلسی دور کرکہ میں محتاج و مسکین ہوں۔", "roman": "Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya yaani jo Shakhs har Namaz ke peeche (baad) hath pasaar (phaila) kar yeh Dua padhe to Allah Tabarak wa Ta'ala par haq hai ke woh us ke hath khaali na phere. Is Hadees ko Hafiz Abu Bakr bin Al-Sunni ne Amal al-Yawm wal-Laylah mein Riwayat kiya.\n\n------------\n(1).. Tarjuma: Aye Allah! Aye mere Ma'bood aur aye Ibrahim wa Ishaq aur Yaqoob Alayhimus Salatu was Salam ke Khuda aur aye Jibraeel wa Mikaeel aur Israfeel Alayhimus Salam ke Rabb! Mujh lachar ki Dua Qubool farma, aur main mubtala-e-mushkilaat hoon, mere deen mein meri hifazat farma, aur mujh gunahgar par apni rahmat nazil farma aur mujh se muflisi door kar ke main muhtaj wa Miskeen hoon."}, {"id": 6330, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 36, "arabic": "عَنِ ابْنِ عَبَّاسٍ قَالَ ، قَالَ رسول صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم إِجْعَلُوْا أَئِمَّتَکُمْ خِیَارَکُمْ فَإِنَّھُمْ وَفْدُکُمْ فِیْمَا بَیْنَکُمْ وَبَیْنَ رَبِّکُمْ۔ رَوَاہٗ الدَّارقُطْنِیْ ( الدار قطنی ۱؍۱۹۷۔ )", "urdu": "فرمایا حضور نبی کریم رؤ ف الرحیم صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے کہ اپنے امام برگزیدہ لوگوں کو بناؤ کہ وہ تمہارے اور تمہارے رب کے درمیان تمہارے ایلچی(سفیر) ہیں۔ اس کو دارقطنی نے روایت کیا۔", "roman": "Farmaya Huzoor Nabi Kareem Raufur Raheem Sallallahu Alaihi Wasallam ne ke apne Imam barguzida logon ko banao ke woh tumhare aur tumhare Rabb ke darmiyan tumhare eelchi (safeer) hain. Is ko Daraqutni ne Riwayat kiya."}, {"id": 6331, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 37, "arabic": "عَنِ السَّائِبِ بْنِ خَلَّادٍ قَالَ إِنَّ رَجُلاً أَمَّ قَوْمًا فَبَصَقَ فِیْ الْقِبْلَۃِ وَ رسولُ اﷲ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم یَنْظُرُ فَقَالَ رسول اﷲ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم لِقَوْمِہٖ حِیْنَ فََرَغ لَا یُصَلِّیْ لَکُمْ فَأَرَادَ بَعْدَ ذٰلِکَ أَنْ یُصَلِّیَ لَھُمْ فَمَنَعُوْہُ فَأَخْبَرُوْہُ بِقُوْلِ رسول اﷲِ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم فَذَکَرَ ذٰلِکَ لِرَسُوْلِ ﷲ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم فَقَالَ نَعَمْ وَحَسِبْتُ أَنَّہ‘ قَالَ إِنَّکَ قَدْ اٰذَیتَ اﷲَ وَرَسُوْلَہ۔(المشکوٰۃ،۶۳)", "urdu": "حضرت سیدنا سائب بن خلاد رَضِیَ اﷲ تَعَالٰی عَنْہُ کہتے ہیں کہ ایک شخص نے ایک قوم کی اِمامت کی اور قبلہ کی طرف منہ کرکے تھوکا رسول کریم صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم دیکھ رہے تھےحضور صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے اس کی قوم کو فرمایا جب وہ فارغ ہوا کہ یہ تمہیں نماز نہ پڑھائے پھر جب وہ نماز پڑھانے لگا تو لوگوں نے اسے منع کیا اور رسول کریم صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کے فرمان کی اسے خبر دی تو اس نے رسول کریم صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کے پاس ذکر کیا تو آپ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا ہاں ( میں نے منع کیا ہے ) راوی کہتے ہیں میں گمان کرتا ہوں کہ آپ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے یہ بھی فرمایا کہ تو نے اﷲ عَزَّوَجَلَّ اور اس کے رسول صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کو ایذا دی۔", "roman": "Hazrat Sayyiduna Sa'ib bin Khallad RadiyAllahu Anhu kehte hain ke ek Shakhs ne ek qaum ki imamat ki aur Qiblah ki taraf munh karke thooka, Rasool-e-Kareem Sallallahu Alaihi Wasallam dekh rahe the. Huzoor Sallallahu Alaihi Wasallam ne us ki qaum ko farmaya jab woh farigh hua ke yeh tumhein Namaz na padhaye. Phir jab woh Namaz padhane laga to logon ne use mana kiya aur Rasool-e-Kareem Sallallahu Alaihi Wasallam ke farman ki use khabar di to us ne Rasool-e-Kareem Sallallahu Alaihi Wasallam ke paas zikr kiya to Aap Sallallahu Alaihi Wasallam ne farmaya haan (main ne mana kiya hai). Raawi kehte hain main gumaan karta hoon ke Aap Sallallahu Alaihi Wasallam ne yeh bhi farmaya ke tu ne Allah Azza wa Jall aur us ke Rasool Sallallahu Alaihi Wasallam ko eeza di."}, {"id": 6332, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 38, "arabic": "عَنِ ابْنِ عَبَّاسٍ رَضِیَ اﷲ عَنْھُمَا قَالَ کُنْتُ اَعْرِفُ اِنْقِضَاءَ صَلوٰۃِ رسول اﷲ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم بِالتَّکْبِیْرِ ۔ مُتَّفَقٌ عَلَیْہِ( صحیح البخاری ۱/۱۱۶، الصحیح لمسلم ۱/۲۱۷۔ )", "urdu": "حضرت سیدنا ابن عباس رَضِیَ اﷲ تَعَالٰی عَنْہُمَا فرماتے ہیں کہ میں رسول کریم ، رؤف رّحیم صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم کا نماز سے فارغ ہونا تکبیر (کی آواز) سے پہچان لیا کرتا تھا۔", "roman": "Hazrat Sayyiduna Ibn Abbas RadiyAllahu Anhuma farmate hain ke main Rasool-e-Kareem, Raufur Raheem Sallallahu Alaihi Wasallam ka Namaz se farigh hona Takbeer (ki aawaz) se pehchan liya karta tha."}, {"id": 6333, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 39, "arabic": "عَنْ أنَسٍ رَضِیَ اﷲ تَعَالٰی عَنْہُ قَالَ ، قَالَ رسول اﷲ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم مَنْ صَلَّی الْفَجْرَ فِیْ جَمَاعَۃٍ ثُمَّ قَعَدَ یَذْکُرُ اللّٰہَ حَتّیٰ تَطْلُعَ الشَّمْسُ ثُمَّ صَلّی رَکْعَتَیْنِ کَانَتْ لَہ کَأَجْرِ حَجَّۃٍ وَّعُمْرَۃٍ قَالَ قَالَ رسول اﷲ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم تَامَّۃٍ تَامَّۃٍ تَامَّۃٍ ۔ رَوَاہٗ التِّرْمِذِیُّ ( جَامِعُ الْتِرْمِذِیْ ،کِتَابُ الْجُمُعَۃِ ص ۶۰ ۔ )", "urdu": "حضور سراپا نور صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا جو شخص فجر کی نماز جماعت کے ساتھ پڑھ کر اﷲ عزوجل کا ذکر کرتا ہوا بیٹھا رہے یہاں تک کہ سورج نکل آئے پھردورکعت نماز پڑھے اسے حج اور عمرہ کا ثواب ملتا ہے۔ حضور صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے تین بار فرمایا کہ پورے حج و عمرہ کا۔ اس کو ترمذی نے روایت کیا۔", "roman": "Huzoor Sarapa Noor Sallallahu Alaihi Wasallam ne farmaya jo Shakhs Fajr ki Namaz Jama'at ke saath padh kar Allah Azza wa Jall ka zikr karta hua baitha rahe yahan tak ke sooraj nikal aaye phir do rakat Namaz padhe use Hajj aur Umrah ka sawab milta hai. Huzoor Sallallahu Alaihi Wasallam ne teen baar farmaya ke poore Hajj wa Umrah ka. Is ko Tirmizi ne Riwayat kiya."}, {"id": 6334, "bookId": 9, "bookName": "اربَعیْنِ حَنفِیَّہ", "volId": 10, "chapterId": 0, "chapterTitle": "", "hadithNo": 40, "arabic": "عَنْ مُعَاوِیَۃَ قَالَ ، قَالَ رسول اﷲ صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم مَنْ یُرِدِ اﷲُ بِہٖ خَیْرًا یُفَقِّھْہُ فِیْ الدِّیْنِ وَاِنَّمَا اَنَا قَاسِمٌ وَ اﷲ یُعْطِيْ۔ مُتَّفَقٌ عَلَیْہِ( صحیح البخاری ۱؍۳۹ ، ۲؍۹۳۹، ۶؍۲۶۶۷ ، الصحیح لِمسلم ۲؍۷۱۹۔ )", "urdu": "حضرت سیدنا معاویہ رَضِیَ اﷲ تَعَالٰی عَنْہُ سے مروی ہے رسول کریم صَلَّی اﷲ تَعَالٰی عَلَیْہِ وَاٰلِہٖ وَسَلَّم نے فرمایا کہ جس شخص کے حق میں اﷲ تعالیٰ بہتری کا ارادہ رکھتا ہے اسے دین کی سمجھ دیتا ہے ۔یعنی اسے عالم فقیہ بنادیتا ہے۔ سوائے اس کے نہیں میں تقسیم کرنے والا ہوں(1)اورخدا تعالیٰ دیتا ہے۔ یعنی ہر وہ چیز کہ خدا دیتا ہے اس کو میں تقسیم کرنے والا ہوں ۔", "roman": "Hazrat Sayyiduna Muawiyah RadiyAllahu Anhu se Marwi hai Rasool-e-Kareem Sallallahu Alaihi Wasallam ne farmaya ke jis Shakhs ke haq mein Allah Ta'ala behtari ka iradah rakhta hai use deen ki samajh deta hai. Yaani use aalim faqeeh bana deta hai. Siwaye is ke nahi main taqseem karne wala hoon (1) aur Khuda Ta'ala deta hai. Yaani har woh cheez ke Khuda deta hai us ko main taqseem karne wala hoon."}];
